"""Preserve earlier story/dialogue texts and give them real paired recordings too."""
import json,pathlib
ROOT=pathlib.Path(__file__).resolve().parents[1]
lines=[('story-01','Omar is in a new city. He sees a small café.','عمر في مدينة جديدة، ويرى مقهى صغيرًا.','can-02'),('story-02',"I'd like to order a coffee.",'أود طلب قهوة.','can-02'),('story-03','Of course. Can I get you anything else?','بالطبع. هل أحضر لك شيئًا آخر؟','can-02'),('story-04','Yes! I want to learn more about this city.','نعم، أريد أن أعرف المزيد عن هذه المدينة.','can-02'),('story-05',"Let's start with the park. It's beautiful.",'لنبدأ بالحديقة، إنها جميلة.','lets-01'),('dialogue-cafe','Hi! Welcome to our café. What would you like to order?','أهلًا بك في مقهانا، ماذا تود أن تطلب؟','can-02'),('dialogue-hotel','Good evening! Welcome to our hotel. How can I help you?','مساء الخير، أهلًا بك في فندقنا. كيف أساعدك؟','like-01'),('dialogue-station','Hello! Where would you like to go today?','مرحبًا، إلى أين تود الذهاب اليوم؟','know-01'),('dialogue-friend','Hi! We have a free afternoon. What shall we do?','مرحبًا، لدينا وقت فراغ بعد الظهر. ماذا نفعل؟','lets-01'),('dialogue-work','Morning! What are you working on today?','صباح الخير، ما الذي تعمل عليه اليوم؟','have-01'),('dialogue-memory','Tell me about where you lived when you were younger.','حدثني عن المكان الذي كنت تعيش فيه عندما كنت أصغر.','used-01'),('dialogue-more','Thanks! Could you tell me a little more about what you need?','شكرًا، هل تخبرني بالمزيد عما تحتاج إليه؟','need-08'),('dialogue-else','Of course. Is there anything else you would like?','بالطبع. هل تود شيئًا آخر؟','like-02'),('dialogue-transfer','Thank you! Now try this in a new situation. What would you say at a hotel?','شكرًا، جرّب ذلك الآن في موقف جديد. ماذا تقول في فندق؟','like-01')]
p=ROOT/'dist/supplement.json';prev={s['id']:s for s in json.loads(p.read_text())['sentences']}if p.exists() else {};rows=[]
for sid,en,ar,scene in lines:rows.append(prev.get(sid)or{'id':sid,'en':en,'ar':ar,'scene_id':scene,'recordings':{g:{'voice_id':v,'path':f'assets/audio/supplement-{sid}-{g}.mp3','status':'pending','words':[]}for g,v in [('male','am_adam'),('female','af_bella')]}})
p.write_text(json.dumps({'schema':1,'sentences':rows},ensure_ascii=False,indent=2));print(len(rows),'supplementary sentences')
